s2_ship_pct:
-- Assumption: fulfilled orders = status IN (2,3); shipping fees summed at order level, net revenue summed at line level
SELECT (
  (SELECT SUM(o.shipping_fee) FROM orders o WHERE o.status IN (2, 3))
  /
  (SELECT SUM(oi.line_total) FROM order_items oi JOIN orders o ON oi.order_id = o.order_id WHERE o.status IN (2, 3))
) * 100 AS shipping_pct_of_net_revenue;

s3_net_of_refunds:
-- Assumption: fulfilled orders = status IN (2,3); net revenue minus total refunds (refunds not restricted to fulfilled orders since returns table has no status link)
SELECT (
  (SELECT SUM(oi.line_total) FROM order_items oi JOIN orders o ON oi.order_id = o.order_id WHERE o.status IN (2, 3))
  -
  (SELECT SUM(refund_amount) FROM returns)
) AS net_revenue_after_refunds;
